def reverse_list(head: "ListNode | None") -> "ListNode | None":
    prev = None
    while head is not None:
        nxt = head.next          # save the rest before overwriting the link
        head.next = prev
        prev, head = head, nxt
    return prev                  # the old tail is the new head


